
import { defineComponent } from "vue";
import {mapState} from "vuex";
import { IonPage, IonContent, IonHeader, IonToolbar, IonTitle, IonButton, IonButtons, IonList, IonItem, IonLabel, IonAccordionGroup, IonAccordion } from "@ionic/vue";
import {FontAwesomeIcon} from "@fortawesome/vue-fontawesome";
import {Capacitor} from "@capacitor/core";
import {App} from "@capacitor/app";

export default defineComponent({
  name: "SettingsAboutAndFAQsView",
  components: {
    IonButtons,
    IonButton,
    IonPage,
    IonContent,
    IonHeader,
    IonToolbar,
    IonTitle,
    IonList,
    IonItem,
    IonLabel,
    IonAccordion,
    IonAccordionGroup,
    FontAwesomeIcon
  },
  computed: {
    ...mapState(['settings']),
  },
  data() {
    return {
      data: {
        appVersion: '1.0.0'
      }
    }
  },
  async beforeMount() {
    // Get the app version.
    const info = await App.getInfo();
    this.data.appVersion = info.version;
  },
  methods: {
    backToSettings() {
      this.$router.push({
        name: 'settings',
        params: {
          transition: 'slide-left'
        }
      })
    }
  }
})
