
import { defineComponent } from "vue";
import {mapState} from "vuex";
import {
  IonPage,
  IonContent,
  IonHeader,
  IonToolbar,
  IonTitle,
  IonList,
  IonLabel,
  IonItem,
  IonToggle,
  alertController
} from "@ionic/vue";
import {FontAwesomeIcon} from "@fortawesome/vue-fontawesome";
import productsHandler from '@/handlers/products.handler';


export default defineComponent({
  name: "SettingsIndexView",
  components: {
    IonLabel,
    IonPage,
    IonContent,
    IonHeader,
    IonToolbar,
    IonTitle,
    IonItem,
    IonList,
    IonToggle,
    FontAwesomeIcon
  },
  computed: {
    ...mapState(['settings'])
  },
  data() {
    return {
      darkMode: false
    }
  },
  watch: {
    darkMode(value) {
      if(value) {
        this.$store.dispatch('setDarkMode');
      }else{
        this.$store.dispatch('setLightMode');
      }
    }
  },
  beforeMount() {
      this.darkMode = this.settings.theme.darkMode;
  },
  methods: {
    // Methods to go here.
    navigate(route: string) {
      this.$router.push({
        name: route,
        params: {
          transition: 'slide-right'
        }
      })
    },
    restorePurchases() {
      productsHandler.restorePurchases();
    },
    purchaseNoAds() {
      productsHandler.purchaseProduct("remove_advertisements").then();
    },
    async feedbackMessage() {
      const alert = await alertController.create({
        header: 'Give Feedback',
        message: 'You will be redirected to the ParkPal website to leave feedback  using the feedback form, would you like to continue?',
        buttons: [
          {
            text: 'Cancel',
            role: 'cancel'
          },
          {
            text: 'OK',
            role: 'confirm',
            handler: () => {
              window.location.href =  'https://parkpal.co.uk/#getintouch';
            },
          },
        ],
      });

      await alert.present();
    },
  }
})
